// Local-phase allow-list (docs/data/tier2-local-phase-handoff.md piece L3, docs/276 rank 5): the local-phase definitions whose
// tier-2 verdict is `ready` (groups local-sampled and row5-candidate of docs/data/autonomy-tier2.csv, which
// tools/autonomy-tier2.ts writes), emitted as mods/ts3fixes/src/AutShadowLocalList.cs. Regenerate after every row-lane merge
// that rewrites the CSV; never hand-edit the generated file.
//   node tools/autonomy-allow-local.ts            write the .cs
//   node tools/autonomy-allow-local.ts --check    exit 1 when the .cs differs from the CSV (selftest-all)
//   node tools/autonomy-allow-local.ts --self-check
import { readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const CSV = join(ROOT, 'docs', 'data', 'autonomy-tier2.csv');
const OUT = join(ROOT, 'mods', 'ts3fixes', 'src', 'AutShadowLocalList.cs');
const GROUPS = new Set(['local-sampled', 'row5-candidate']);
const TYPE = /^[A-Za-z_][\w.]*(\+[\w]+)+$/;  // a nested definition type name (Outer+Inner+Definition), not "base path: ..."

// no quoted commas in the columns read here (group, definition_type, verdict come before any free text)
export function localNames(csv: string): string[] {
  const rows = csv.trim().split(/\r?\n/).map((l) => l.split(','));
  const h = rows[0], g = h.indexOf('group'), d = h.indexOf('definition_type'), v = h.indexOf('verdict');
  if (g < 0 || d < 0 || v < 0) throw new Error('autonomy-tier2.csv: group / definition_type / verdict column missing');
  return [...new Set(rows.slice(1).filter((r) => GROUPS.has(r[g]) && r[v] === 'ready' && TYPE.test(r[d])).map((r) => r[d]))].sort();
}

export function emit(names: string[]): string {
  return `// Generated by tools/autonomy-allow-local.ts from docs/data/autonomy-tier2.csv. Do not edit by hand.
// ${names.length} local-phase definitions with tier-2 verdict ready (groups local-sampled, row5-candidate). Type names only.
namespace Ts3Fixes
{
    public static class AutShadowLocalList
    {
        public static readonly string[] Names = {
${names.map((n) => `            "${n}",`).join('\n')}
        };
    }
}
`;
}

if (/autonomy-allow-local\.ts$/.test(process.argv[1] ?? '')) {
  if (process.argv.includes('--self-check')) {
    const csv = 'group,entry_rank,definition_type,assembly,verdict\nlocal-sampled,1,A.B+C+Definition,x,ready\n'
      + 'local-sampled,2,A.B+D+Definition,x,blocked\nbase-local,3,A.E+F+Definition,x,ready\nrow5-candidate,4,base path: X.Y,,ready\n'
      + 'row5-candidate,5,A.G+H+Definition,x,ready\nmeta-rest,6,A.I+J+Definition,x,ready\nlocal-sampled,7,A.B+C+Definition,x,ready';
    const got = localNames(csv).join(';'), want = 'A.B+C+Definition;A.G+H+Definition';
    if (got !== want) { console.error(`autonomy-allow-local self-check FAIL: ${got} != ${want}`); process.exit(1); }
    if (!emit(['A.B+C+Definition']).includes('"A.B+C+Definition",')) { console.error('autonomy-allow-local self-check FAIL: emit'); process.exit(1); }
    console.log('autonomy-allow-local self-check: ok');
  } else {
    const text = emit(localNames(readFileSync(CSV, 'utf8')));
    if (process.argv.includes('--check')) {
      let cur = '';
      try { cur = readFileSync(OUT, 'utf8').replace(/\r\n/g, '\n'); } catch { /* missing = stale */ }
      if (cur !== text) { console.error('AutShadowLocalList.cs is stale: run node tools/autonomy-allow-local.ts'); process.exit(1); }
      console.log('autonomy-allow-local: AutShadowLocalList.cs matches the CSV');
    } else { writeFileSync(OUT, text); console.log(`wrote ${OUT}`); }
  }
}
